style.css:
@-moz-document domain("google.com") {
/* ===========================
   BACKGROUND
   =========================== */

body {
    background: url(https://imgur.com/sJH2MbP) center center / cover no-repeat fixed !important;
}

/* Hide original Google logo */
.lnXdpd,
#hplogo,
.logo {
    display: none !important;
}

/* Custom Google logo */
div[role="main"] {
    position: relative;
}

div[role="main"]::before {
    content: "";
    display: block;
    width: 420px;
    height: 150px;
    margin: 20px auto 15px;
    background: url(https://imgur.com/sJH2MbP) center/contain no-repeat;
}

/* Search bar */
.APjFqb,
.a4bIc,
.RNNXgb,
.gLFyf {
    background: #FFFCE8 !important;
    border: 3px solid #B7D9F7 !important;
    border-radius: 50px !important;
    color: #6E8FB4 !important;
    box-shadow: 0 8px 20px rgba(183,217,247,.45) !important;
}

/* Search bar hover */
.RNNXgb:hover {
    box-shadow: 0 12px 30px rgba(183,217,247,.65) !important;
}

/* Search text */
.gLFyf {
    color: #7B9CC0 !important;
}

/* Buttons */
.gNO89b,
.RNmpXc {
    background: #FFF6BE !important;
    color: #6E8FB4 !important;
    border: 2px solid #B7D9F7 !important;
    border-radius: 20px !important;
    transition: .25s;
}

.gNO89b:hover,
.RNmpXc:hover {
    background: #B7D9F7 !important;
    color: white !important;
}

/* Links */
a {
    color: #7CAED9 !important;
}

/* Header */
#gb {
    background: rgba(255,255,255,.35) !important;
    backdrop-filter: blur(10px);
}

/* Footer */
.uU7dJb {
    background: rgba(255,255,255,.35) !important;
    backdrop-filter: blur(10px);
}

/* Icons */
.L3eUgb svg {
    fill: #7CAED9 !important;
}

/* Rounded animations */
* {
    transition: .25s ease;
}
}
